const icon=(name='star')=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.star}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString('ar-SA');
const KEY='rijaa-demo-v1';
const templates=[{id:'coffee',name:'قهوة ولقاء',category:'كافيه',icon:'coffee',color:'#204b3c',accent:'#d6ff76',target:4,reward:'قهوة مجانية',pattern:true,terms:'ختم واحد لكل مشروب مؤهل ومدفوع. المكافأة قهوة بالحجم العادي. لا تحتسب المكافأة زيارة مدفوعة.'},{id:'car',name:'لمعة جديدة',category:'مغسلة سيارات',icon:'car',color:'#173e6a',accent:'#9cdaff',target:4,reward:'غسلة مجانية',pattern:false,terms:'ختم لكل غسلة خارجية مدفوعة. المكافأة غسلة خارجية. لا تجمع مع العروض الأخرى.'},{id:'shop',name:'اختيارك أجمل',category:'متجر',icon:'bag',color:'#653747',accent:'#ffdbb6',target:6,reward:'خصم ٥٠ ريالًا',pattern:true,terms:'ختم لكل فاتورة مؤهلة. الخصم على الزيارة التالية بعد اكتمال الأختام.'},{id:'salon',name:'موعد العناية',category:'صالون',icon:'scissors',color:'#593d75',accent:'#e9d0ff',target:5,reward:'جلسة عناية مجانية',pattern:false,terms:'ختم لكل خدمة مؤهلة ومدفوعة. المكافأة خدمة العناية المحددة لدى الفرع.'}];
function seed(){return{shops:[{id:'cafe',name:'قهوة ولقاء',status:'active',branch:'فرع الياسمين',card:{...templates[0],logo:''},employees:[{id:'e1',name:'سارة أحمد',phone:'0500000001',status:'active'},{id:'e2',name:'خالد علي',phone:'0500000002',status:'active'}],members:[{id:'RJ-C1001',name:'عبدالله',phone:'0500000011',stamps:2,rewards:0,visits:2,joined:Date.now()-86400000*4},{id:'RJ-C1002',name:'نورة',phone:'0500000012',stamps:3,rewards:0,visits:3,joined:Date.now()-86400000*3},{id:'RJ-C1003',name:'محمد',phone:'0500000013',stamps:0,rewards:1,visits:4,joined:Date.now()-86400000*6}],logs:[{id:'seed1',member:'RJ-C1002',name:'نورة',type:'stamp',employee:'سارة أحمد',time:Date.now()-900000},{id:'seed2',member:'RJ-C1001',name:'عبدالله',type:'stamp',employee:'خالد علي',time:Date.now()-2400000},{id:'seed3',member:'RJ-C1003',name:'محمد',type:'reward',employee:'سارة أحمد',time:Date.now()-3700000}]},{id:'wash',name:'مغسلة اللمعة',status:'active',branch:'الفرع الرئيسي',card:{...templates[1],name:'مغسلة اللمعة',logo:''},employees:[{id:'e3',name:'أحمد حسن',phone:'0500000003',status:'active'}],members:[],logs:[]},{id:'store',name:'متجر خيط',status:'active',branch:'الفرع الرئيسي',card:{...templates[2],name:'متجر خيط',logo:''},employees:[{id:'e4',name:'ريم سالم',phone:'0500000004',status:'active'}],members:[],logs:[]}],shop:'cafe',member:'RJ-C1001'};}
let db;try{db=JSON.parse(localStorage.getItem(KEY))||seed();if(!Array.isArray(db.shops)||!db.shops.length)db=seed();}catch{db=seed();}
let role='owner',view='overview',draft=null,clientStage='phone',clientPhone='',clientName='',staffMode='stamp',staffEmployee='',lastTx=null,stream=null,scanFrame=null,scannerLock=false,selectedStaffMember='';
const shop=()=>db.shops.find(s=>s.id===db.shop)||db.shops[0];
const currentMember=()=>shop().members.find(m=>m.id===db.member);
function save(){if(window.RIJAA_DEPLOYED)return;try{localStorage.setItem(KEY,JSON.stringify(db));}catch{toast('تعذر حفظ التجربة في هذا المتصفح.');}}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3500);}
function qr(value){if(typeof qrcode==='undefined')return '<p>تعذر تحميل الرمز</p>';const q=qrcode(0,'M');q.addData(value);q.make();return q.createSvgTag({cellSize:4,margin:2,scalable:true});}
const memberCode=m=>`RIJAA:${shop().id}:${m.id}`;
const joinURL=()=>`${location.origin}${location.pathname}?join=${encodeURIComponent(shop().id)}`;
function cardHTML(c,m=null,full=false){const stamps=m?.stamps??2;return `<div class="loyalty-card ${c.pattern?'pattern':''}" style="--card:${esc(c.color)};--accent:${esc(c.accent)}">${c.background?`<img class="card-background" src="${esc(c.background)}" alt="">`:""}<div class="card-top"><div class="actions"><div class="card-logo">${c.logo?`<img src="${esc(c.logo)}" alt="شعار النشاط" style="width:100%;height:100%;border-radius:12px;object-fit:cover">`:icon(c.icon)}</div><div><div class="card-brand">${esc(c.name)}</div><div class="card-category">${esc(c.category)}</div></div></div><span class="card-tag">رِجعة</span></div><div class="card-title">رصيد زياراتك</div><div class="card-count">${fmt(stamps)} <small>من ${fmt(c.target)}</small></div><div class="stamps">${Array.from({length:c.target},(_,i)=>`<span class="stamp ${i<stamps?'filled':''}">${c.stampImage?`<img class="stamp-image" src="${esc(c.stampImage)}" alt="ختم">`:icon(c.icon)}</span>`).join('')}</div><div class="card-reward">${m?.rewards?`${icon('gift')} لديك ${fmt(m.rewards)} مكافأة جاهزة`:`${esc(c.reward)} بعد ${fmt(c.target)} زيارات`}</div>${full&&m?`<div class="card-divider"></div><div class="card-qr">${qr(memberCode(m))}</div><div class="card-member">${esc(m.name||'عضو رِجعة')} · ${esc(m.id)}</div>`:`<div class="card-divider"></div><div class="card-footer"><span>${m?.name?esc(m.name):'بطاقة الولاء'}</span><span>${fmt(c.target-stamps)} زيارات للمكافأة</span></div>`}</div>`;}
const navOwner=[['overview','dashboard','نظرة عامة'],['design','card','تصميم البطاقة'],['customers','users','العملاء'],['employees','shield','الموظفون'],['join','link','رابط التسجيل'],['activity','clock','سجل العمليات']];
const navAdmin=[['overview','dashboard','نظرة عامة'],['shops','building','الأنشطة'],['templates','card','قوالب المنصة'],['activity','clock','العمليات']];
function stopCamera(){if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;if(scanFrame)cancelAnimationFrame(scanFrame);scanFrame=null;}
function render(){stopCamera();const s=shop()||{employees:[],card:{icon:"star"},name:"رِجعة",branch:""};if(!s.employees.some(e=>e.id===staffEmployee&&e.status==='active'))staffEmployee=s.employees.find(e=>e.status==='active')?.id||'';const client=role==='client';const nav=role==='admin'?navAdmin:role==='staff'?[['scan','scan','إضافة الأختام'],['activity','clock','عمليات الفرع']]:navOwner;document.querySelector('#app').innerHTML=`<div class="${client?'':'app-shell'}">${client?'':`<aside class="sidebar"><a href="#" class="brand" data-action="role" data-role="owner"><span class="brand-symbol">${icon('refresh')}</span><span>رِجعة<small>نظام الولاء</small></span></a><div class="side-label">${role==='admin'?'إدارة المنصة':role==='staff'?'مساحة الموظف':'مساحة نشاطك'}</div><nav class="side-nav" aria-label="القائمة الرئيسية">${nav.map(([id,ic,label])=>`<button data-action="nav" data-view="${id}" class="${view===id?'active':''}">${icon(ic)}${label}</button>`).join('')}</nav><div class="sidebar-foot"><div class="shop-chip"><span class="avatar">${icon(role==='admin'?'shield':s.card.icon)}</span><div><strong>${role==='admin'?'إدارة رِجعة':esc(s.name)}</strong><small>${role==='admin'?'حساب مدير المنصة':esc(s.branch)}</small></div></div><button class="reset" data-action="reset">إعادة ضبط بيانات التجربة</button></div></aside>`}<div class="workspace"><header class="topbar"><div class="role-switch" aria-label="تبديل دور التجربة">${[['owner','صاحب النشاط'],['staff','الموظف'],['client','العميل'],['admin','الأدمن']].map(([r,label])=>`<button class="${role===r?'active':''}" data-action="role" data-role="${r}">${label}</button>`).join('')}</div><div class="demo-label"><span class="demo-dot"></span>تجربة تفاعلية · البيانات محفوظة في هذا المتصفح<button data-action="help" aria-label="عن التجربة" style="background:none;color:inherit">${icon('shield')}</button></div></header>${client?clientHTML():`<main class="main">${role==='admin'?adminHTML():role==='staff'&&view==='scan'?staffHTML():ownerHTML()}</main>`}</div></div>`;if(view==='design'&&role==='owner')bindEditor();if(role==='staff'&&view==='scan')document.querySelector('#manual-code')?.focus({preventScroll:true});}
const head=(eyebrow,title,sub,action='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="sub">${sub}</p></div>${action}</div>`;
function statsHTML(s){return `<div class="stats">${[[s.members.length,'عملاء البرنامج','users','بطاقات مسجلة'],[s.logs.filter(l=>new Date(l.time).toDateString()===new Date().toDateString()&&l.type==='stamp').length,'أختام اليوم','star','زيارات مسجلة اليوم'],[s.members.reduce((n,m)=>n+m.rewards,0),'مكافآت جاهزة','gift','بانتظار الاستخدام'],[s.employees.filter(e=>e.status==='active').length,'موظفون نشطون','shield','يمكنهم إضافة الأختام']].map(([n,t,i,sub])=>`<div class="stat"><div class="stat-top"><span>${t}</span>${icon(i)}</div><div class="stat-value">${fmt(n)}</div><small>${sub}</small></div>`).join('')}</div>`;}
function logsHTML(logs,limit=50){return logs.length?`<div class="activity">${logs.slice(0,limit).map(l=>`<div class="activity-row"><span class="avatar">${icon(l.type==='redeem'?'gift':l.type==='undo'?'refresh':'coffee')}</span><div class="grow"><strong>${esc(l.name)}</strong><small>${esc(l.employee)}${l.shopName?' · '+esc(l.shopName):''}</small></div><div><b>${l.type==='redeem'?'استخدام مكافأة':l.type==='undo'?'تراجع عن العملية':l.type==='reward'?'استحقاق مكافأة':'إضافة ختم'}</b><div class="line-meta">${new Date(l.time).toLocaleTimeString('ar-SA',{hour:'2-digit',minute:'2-digit'})} · ${new Date(l.time).toLocaleDateString('ar-SA',{month:'short',day:'numeric'})}</div></div></div>`).join('')}</div>`:`<div class="empty">لا توجد عمليات بعد. أول ختم سيظهر هنا.</div>`;}
function ownerHTML(){const s=shop();if(view==='design')return designHTML();if(view==='templates'){view='design';return designHTML();}if(view==='customers')return customersHTML();if(view==='employees')return employeesHTML();if(view==='join')return joinHTML();if(view==='activity')return head('سجل نشاطك','كل زيارة، محفوظة','راجع الأختام والمكافآت وتصحيحات الموظفين.')+`<div class="panel">${logsHTML(s.logs)}</div>`;return head('أهلًا بك في رِجعة',s.name,'كل زيارة تقرّب عميلك من رجعته القادمة.',`<button class="btn primary" data-action="nav" data-view="join">${icon('link')} رابط التسجيل</button>`)+statsHTML(s)+`<div class="grid-two"><section class="panel"><div class="panel-head"><div><h2>آخر الزيارات</h2><p>ما يحدث في برنامجك الآن</p></div><button class="btn quiet small" data-action="nav" data-view="activity">عرض الكل</button></div>${logsHTML(s.logs,4)}<div class="tip">${icon('scan')}<div><strong>ختم واحد. بخطوة واحدة.</strong><p>افتح واجهة الموظف وجرّب إضافة ختم إلى بطاقة عميل.</p></div></div><div class="quick-links"><button class="btn secondary" data-action="role" data-role="staff">${icon('scan')} واجهة الموظف</button><button class="btn secondary" data-action="role" data-role="client">${icon('phone')} رحلة العميل</button></div></section><section class="panel"><div class="panel-head"><div><h2>بطاقتك الحالية</h2><p>${fmt(s.card.target)} زيارات، ثم ${esc(s.card.reward)}</p></div><span class="pill">${s.status==='active'?'فعّالة':'موقوفة'}</span></div>${cardHTML(s.card)}<button class="btn secondary full mt" data-action="nav" data-view="design">${icon('settings')} تعديل البطاقة</button></section></div>`;}
function templatesHTML(){return head(role==='admin'?'هوية لكل نشاط':'ابدأ بقالب جاهز','بطاقة تشبه نشاطك','اختر نقطة البداية، وغيّر كل ما تحتاجه.')+`<div class="templates">${templates.map(t=>`<article class="template-card">${cardHTML(t)}<div class="template-info"><h3>${esc(t.category)}</h3><p>${esc(t.reward)} بعد ${fmt(t.target)} زيارات</p><button class="btn secondary full" data-action="template" data-id="${t.id}">استخدام القالب</button></div></article>`).join('')}</div>`;}
function designHTML(){draft??=structuredClone(shop().card);return head('هوية برنامجك','صمّم بطاقتك','كل تغيير يظهر أمامك مباشرة.',`<button class="btn primary" data-action="save-card">${icon('check')} حفظ البطاقة</button>`)+`<div class="editor-grid"><section class="panel"><div class="editor-section"><div class="section-title"><span class="section-number">١</span><h2>اسم وهوية</h2></div><label class="field"><span>اسم النشاط على البطاقة</span><input class="input" id="card-name" data-card="name" maxlength="36" value="${esc(draft.name)}"></label><div class="form-row"><label class="field"><span>نوع النشاط</span><select data-card="category">${['كافيه','مغسلة سيارات','متجر','صالون','مطعم','نشاط آخر'].map(c=>`<option ${draft.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field"><span>شعار النشاط</span><input class="input" id="logo-file" type="file" accept="image/png,image/jpeg,image/webp"><small>صورة PNG أو JPG أو WebP، حتى ١ ميجابايت</small></label></div>${draft.logo?'<button class="btn quiet small" data-action="remove-logo">إزالة الشعار</button>':''}</div><div class="editor-section"><div class="section-title"><span class="section-number">٢</span><h2>الألوان والأختام</h2></div><label class="field"><span>لون البطاقة</span><div class="swatches">${['#204b3c','#173e6a','#653747','#593d75','#24292e','#9a4829'].map(c=>`<button class="swatch ${draft.color===c?'active':''}" style="background:${c}" data-action="color" data-value="${c}" aria-label="لون ${c}"></button>`).join('')}<input type="color" value="${esc(draft.color)}" data-card="color" aria-label="لون مخصص للبطاقة"></div></label><label class="field"><span>لون الأختام</span><input type="color" value="${esc(draft.accent)}" data-card="accent" aria-label="لون الأختام"></label><div class="field"><span>أيقونة الأختام</span><div class="icon-options">${[['coffee','قهوة'],['car','سيارة'],['bag','تسوق'],['scissors','صالون'],['star','نجمة'],['heart','قلب']].map(([i,label])=>`<button class="icon-choice ${draft.icon===i?'active':''}" data-action="card-icon" data-icon="${i}" aria-label="${label}" title="${label}">${icon(i)}</button>`).join('')}</div></div><div class="field"><span>الخلفية</span><div class="segmented"><button class="${!draft.pattern?'active':''}" data-action="pattern" data-value="plain">لون سادة</button><button class="${draft.pattern?'active':''}" data-action="pattern" data-value="dots">نقشة خفيفة</button></div></div></div><div class="form-row"><label class="field"><span>صورة خلفية مخصصة</span><input class="input" id="background-file" type="file" accept="image/png,image/jpeg,image/webp"><small>اختياري · تظهر بخفة خلف معلومات البطاقة</small></label><label class="field"><span>صورة ختم مخصصة</span><input class="input" id="stamp-file" type="file" accept="image/png,image/jpeg,image/webp"><small>اختياري · صورة مربعة واضحة</small></label></div><div class="actions">${draft.background?'<button class="btn quiet small" data-action="clear-background">إزالة الخلفية</button>':''}${draft.stampImage?'<button class="btn quiet small" data-action="clear-stamp">إزالة صورة الختم</button>':''}</div><div class="editor-section"><div class="section-title"><span class="section-number">٣</span><h2>الزيارات والمكافأة</h2></div><div class="form-row"><label class="field"><span>عدد الزيارات المطلوبة</span><select data-card="target">${Array.from({length:11},(_,i)=>i+2).map(n=>`<option value="${n}" ${draft.target===n?'selected':''}>${fmt(n)} زيارات</option>`).join('')}</select></label><label class="field"><span>المكافأة</span><input class="input" data-card="reward" value="${esc(draft.reward)}" maxlength="45"></label></div><label class="field"><span>شروط البرنامج</span><textarea data-card="terms" rows="3" maxlength="600">${esc(draft.terms)}</textarea><small>وضّح الزيارة المؤهلة ونوع المكافأة.</small></label></div></section><aside class="editor-preview"><h3>معاينة مباشرة</h3><div id="card-preview">${cardHTML(draft)}</div><p class="preview-note">معاينة تصميم · قد يختلف ترتيب الحقول في محفظة الجوال</p><div class="tip">${icon('gift')}<div><strong>عرض واضح، رجعة أسهل.</strong><p>اسم قصير ومكافأة محددة يساعدان العميل على فهم البرنامج.</p></div></div></aside></div>`;}
function updatePreview(){document.querySelector('#card-preview').innerHTML=cardHTML(draft);}
function bindEditor(){for(const [id,key] of [['background-file','background'],['stamp-file','stampImage']])document.getElementById(id)?.addEventListener('change',event=>{const file=event.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>1048576){toast('اختر صورة أقل من ١ ميجابايت.');event.target.value='';return;}const reader=new FileReader();reader.onload=()=>{draft[key]=reader.result;updatePreview();};reader.readAsDataURL(file);});document.querySelectorAll('[data-card]').forEach(el=>el.addEventListener('input',()=>{draft[el.dataset.card]=el.dataset.card==='target'?Number(el.value):el.value;updatePreview();}));document.querySelector('#logo-file').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>1048576){toast('اختر صورة PNG أو JPG أو WebP أقل من ١ ميجابايت.');e.target.value='';return;}const reader=new FileReader();reader.onload=()=>{draft.logo=reader.result;updatePreview();};reader.readAsDataURL(f);});}
function customersHTML(){const s=shop();return head('أصحاب الرجعة','عملاء البرنامج','الرصيد والمكافآت في مكان واحد.')+`<section class="panel"><div class="search-row"><input class="input" id="customer-search" placeholder="ابحث بالاسم أو رقم الجوال" aria-label="البحث عن عميل"><span class="pill gray">${fmt(s.members.length)} عملاء</span></div><div class="table-wrap"><table><thead><tr><th>العميل</th><th>الجوال</th><th>الأختام</th><th>المكافآت الجاهزة</th><th>البطاقة</th></tr></thead><tbody id="customer-rows">${customerRows(s.members)}</tbody></table></div></section>`;}
function customerRows(members){return members.length?members.map(m=>`<tr><td><div class="cell-person"><span class="avatar">${icon('users')}</span><div>${esc(m.name||'عميل')}<small>${esc(m.id)}</small></div></div></td><td dir="ltr" style="text-align:right">${esc(m.phone)}</td><td>${fmt(m.stamps)} / ${fmt(shop().card.target)}</td><td><span class="pill ${m.rewards?'gold':'gray'}">${fmt(m.rewards)}</span></td><td><button class="btn quiet small" data-action="member-card" data-id="${m.id}">عرض</button></td></tr>`).join(''):'<tr><td colspan="5" class="empty">لا توجد نتائج.</td></tr>';}
function employeesHTML(){return head('فريقك','كل موظف، بحسابه','أضف الفريق وحدد من يمكنه تسجيل الزيارات.',`<button class="btn primary" data-action="add-employee">${icon('plus')} إضافة موظف</button>`)+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>الموظف</th><th>رقم الجوال</th><th>الفرع</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>${shop().employees.map(e=>`<tr><td><div class="cell-person"><span class="avatar">${icon('users')}</span>${esc(e.name)}</div></td><td dir="ltr" style="text-align:right">${esc(e.phone)}</td><td>${esc(shop().branch)}</td><td><span class="pill ${e.status==='active'?'':'gray'}">${e.status==='active'?'نشط':'موقوف'}</span></td><td><button class="btn quiet small" data-action="toggle-employee" data-id="${e.id}">${e.status==='active'?'إيقاف الوصول':'تفعيل الوصول'}</button></td></tr>`).join('')}</tbody></table></div></section><div class="tip">${icon('shield')}<div><strong>الأختام باسم الموظف.</strong><p>كل عملية تحفظ باسم من نفذها. تسجيل الدخول هنا تمثيلي للمراجعة؛ الحماية الفعلية تضاف عند التشغيل.</p></div></div>`;}
function joinHTML(){return head('من الكاشير إلى المحفظة','رابط تسجيل عملائك','رابط واحد لكل نشاط. بطاقة مستقلة لكل عميل.')+`<div class="join-layout"><section class="panel"><div class="panel-head"><div><h2>امسح وانضم</h2><p>يمكن عرض الرمز عند الكاشير</p></div>${icon('scan')}</div><div class="qr-block">${qr(joinURL())}</div><div class="join-link">${esc(joinURL())}</div><div class="actions"><button class="btn primary" data-action="copy-link">${icon('link')} نسخ الرابط</button><button class="btn secondary" data-action="download-qr">${icon('download')} تنزيل الرمز</button></div></section><section class="panel"><h2>تجربة العميل</h2><div class="help-list"><div class="help-item"><strong>١. يفتح رابط نشاطك</strong><p>يرى اسم النشاط والعرض وشروط المكافأة.</p></div><div class="help-item"><strong>٢. يسجل برقم جواله</strong><p>التحقق يربط العضوية برقم العميل ويساعده على استرجاعها.</p></div><div class="help-item"><strong>٣. تصدر بطاقته</strong><p>بطاقة شخصية برمز خاص به، يستخدمها في كل زيارة.</p></div></div><button class="btn secondary full mt" data-action="role" data-role="client">${icon('phone')} جرّب التسجيل الآن</button><div class="notice">رابط التجربة يعرض النشاط ببيانات هذا المتصفح. المشاركة بين الأجهزة وتسجيل العملاء الفعلي يحتاجان التشغيل التجاري.</div></section></div>`;}
function staffHTML(){const s=shop(),m=s.members.find(m=>m.id===selectedStaffMember)||s.members[0];return head('واجهة الموظف','زيارة جديدة؟ ختم جديد.','اعرض بطاقة العميل أمام الكاميرا.',`<select class="input staff-select" id="staff-employee" aria-label="الموظف الحالي">${s.employees.filter(e=>e.status==='active').map(e=>`<option value="${e.id}" ${staffEmployee===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select>`)+`<div class="scanner-layout"><section class="scanner"><div class="segmented"><button class="${staffMode==='stamp'?'active':''}" data-action="staff-mode" data-mode="stamp">إضافة ختم</button><button class="${staffMode==='redeem'?'active':''}" data-action="staff-mode" data-mode="redeem">صرف مكافأة</button></div><div class="scan-frame">${icon('scan')}<video id="scan-video" autoplay muted playsinline></video></div><h2 id="scan-title">${staffMode==='stamp'?'جاهز لإضافة ختم':'جاهز لصرف مكافأة'}</h2><p id="scan-status">افتح الكاميرا أو جرّب بطاقة من القائمة.</p><button class="btn lime full" data-action="camera">${icon('camera')} فتح الكاميرا</button><p class="scanner-help">المسح يسجل العملية مباشرة. قد يطلب المتصفح إذن الكاميرا.</p></section><section class="panel">${lastTx?`<div class="scanner-result"><div class="result-mark">${icon('check')}</div><h2>${lastTx.type==='redeem'?'تم صرف المكافأة':'تمت إضافة الختم'}</h2><p class="sub">${esc(lastTx.name)} · ${lastTx.type==='stamp'&&lastTx.earned?'مكافأة جديدة جاهزة!':lastTx.type==='stamp'?`${fmt(lastTx.stamps)} من ${fmt(s.card.target)} زيارات`:'سجلنا استخدام المكافأة'}</p><button class="btn quiet small mt" data-action="undo" ${lastTx.undone?'disabled':''}>${lastTx.undone?'تم التراجع':'تراجع عن هذه العملية'}</button></div>`:''}<h2>جرّب المسح الآن</h2><p class="sub" style="margin-top:5px">اختر عميلًا لمحاكاة قراءة بطاقته.</p><label class="field mt"><span>بطاقة العميل</span><select id="staff-member">${s.members.map(x=>`<option value="${x.id}" ${m?.id===x.id?'selected':''}>${esc(x.name||x.phone)} · ${fmt(x.stamps)} أختام · ${fmt(x.rewards)} مكافآت</option>`).join('')}</select></label><button class="btn primary full" data-action="simulate-scan" ${!m||!staffEmployee||s.status!=='active'?'disabled':''}>${icon('scan')} ${staffMode==='stamp'?'محاكاة مسح وإضافة ختم':'محاكاة مسح وصرف مكافأة'}</button><div class="card-divider" style="background:var(--line)"></div><label class="field"><span>أو أدخل رمز البطاقة</span><input id="manual-code" class="input" placeholder="RJ-C1001" dir="ltr" autocomplete="off"><small>يدعم قارئ QR يكتب الرمز ويضغط Enter.</small></label><button class="btn secondary full" data-action="manual-scan">تسجيل العملية</button>${!staffEmployee?'<p class="error">أضف موظفًا نشطًا من لوحة صاحب النشاط.</p>':''}${s.status!=='active'?'<p class="error">هذا النشاط موقوف من إدارة المنصة.</p>':''}<div class="notice">كل مسح يمثل خدمة مدفوعة واحدة. التحقق من الفاتورة يضاف مع الربط بالكاشير.</div></section></div>`;}
function clientHTML(){const s=shop(),m=currentMember();return `<div class="phone-layout"><section class="journey-intro"><div class="brand" style="margin-bottom:35px"><span class="brand-symbol">${icon('refresh')}</span><span>رِجعة</span></div><div class="eyebrow">بطاقة ${esc(s.name)}</div><h1>زياراتك لها مكافأة.</h1><p>اجمع ${fmt(s.card.target)} زيارات، واستمتع بـ${esc(s.card.reward)}. بطاقتك معك في كل رجعة.</p><div class="steps">${[['phone','رقم الجوال'],['otp','التحقق'],['card','بطاقتك']].map(([st,label],i)=>`<div class="step ${clientStage===st?'active':''}"><span class="step-number">${fmt(i+1)}</span>${label}</div>`).join('')}</div><div class="notice mt">هذه رحلة تجريبية. لا تُرسل رسائل ولا تُصدر بطاقات للمحفظة الفعلية بعد.</div></section><section class="phone"><div class="phone-header"><span class="avatar">${icon(s.card.icon)}</span><h2>${clientStage==='card'?'بطاقتك جاهزة':clientStage==='otp'?'تحقق من رقمك':esc(s.name)}</h2><p>${clientStage==='card'?'اعرض الرمز للموظف في كل زيارة.':clientStage==='otp'?'خطوة واحدة وتصبح البطاقة لك.':`${fmt(s.card.target)} زيارات ثم ${esc(s.card.reward)}`}</p></div>${clientStage==='phone'?`<form id="join-form"><label class="field"><span>رقم الجوال</span><input class="input" name="phone" type="tel" inputmode="tel" placeholder="05xxxxxxxx" dir="ltr" required value="${esc(clientPhone)}" autocomplete="tel"></label><label class="field"><span>الاسم <span class="muted">(اختياري)</span></span><input class="input" name="name" placeholder="كيف نناديك؟" maxlength="35" value="${esc(clientName)}" autocomplete="given-name"></label><label class="terms"><input type="checkbox" name="terms" required><span>أوافق على <button type="button" data-action="terms">شروط برنامج الولاء</button> واستخدام رقمي لإدارة عضويتي.</span></label><button class="btn primary full" type="submit">إصدار بطاقتي</button><p class="error" id="join-error"></p></form><div class="phone-bottom">لديك بطاقة؟ سجل برقمك لاسترجاعها.</div><button class="btn quiet full mt" data-action="existing-client" ${!m?'disabled':''}>عرض بطاقة العميل التجريبي</button>`:clientStage==='otp'?`<form id="otp-form"><p style="text-align:center">رقمك <b dir="ltr">${esc(clientPhone)}</b></p><label class="field"><span>رمز التحقق</span><input class="input otp" name="otp" inputmode="numeric" maxlength="6" placeholder="••••••" autocomplete="one-time-code" dir="ltr" required></label><div class="notice">رمز التجربة: <strong dir="ltr">123456</strong><br>لم تُرسل رسالة فعلية.</div><button class="btn primary full mt" type="submit">تأكيد وإصدار البطاقة</button><p class="error" id="otp-error"></p></form><button class="btn quiet full mt" data-action="back-phone">تعديل رقم الجوال</button>`:m?`${cardHTML(s.card,m,true)}<div class="wallet-buttons"><button class="btn full" data-action="wallet" data-kind="Apple Wallet">${icon('wallet')} إضافة إلى Apple Wallet</button><button class="btn full" data-action="wallet" data-kind="Google Wallet">${icon('wallet')} إضافة إلى Google Wallet</button></div><div class="phone-bottom">أزرار المحفظة تعرض معاينة تجريبية.</div><button class="btn secondary full mt" data-action="client-to-staff">${icon('scan')} جرّب إضافة ختم لهذه البطاقة</button><button class="btn quiet full mt" data-action="back-phone">تسجيل برقم آخر</button>`:'<p class="empty">سجّل برقمك لإصدار البطاقة.</p>'}</section></div>`;}
function adminHTML(){if(view==='templates'){view='design';return designHTML();}if(view==='activity')return head('إدارة المنصة','عمليات الأنشطة','سجل موحد للعمليات في بيانات التجربة.')+`<section class="panel">${logsHTML(db.shops.flatMap(s=>s.logs.map(l=>({...l,shopName:s.name}))).sort((a,b)=>b.time-a.time))}</section>`;if(view==='shops')return shopsHTML();const all=db.shops.flatMap(s=>s.members);return head('إدارة رِجعة','منصة واحدة. رجعات كثيرة.','تابع الأنشطة، وادخل إلى تجربتها.',`<button class="btn primary" data-action="add-shop">${icon('plus')} إضافة نشاط</button>`)+`<div class="stats">${[[db.shops.length,'الأنشطة','building'],[db.shops.filter(s=>s.status==='active').length,'أنشطة فعالة','check'],[all.length,'بطاقات العملاء','card'],[db.shops.reduce((n,s)=>n+s.employees.filter(e=>e.status==='active').length,0),'الموظفون','users']].map(([n,t,i])=>`<div class="stat"><div class="stat-top">${t}${icon(i)}</div><div class="stat-value">${fmt(n)}</div><small>إجمالي بيانات التجربة</small></div>`).join('')}</div>${shopsCards()}<div class="help-banner"><div><h2>جرّب النشاط من الداخل</h2><p>كل نشاط له بطاقة وفريق وعملاء وسجل مستقل.</p></div><button class="btn lime" data-action="open-shop" data-id="${shop().id}">فتح لوحة النشاط</button></div>`;}
function shopsHTML(){return head('أنشطة المنصة','كل نشاط، بمساحته','أضف نشاطًا أو تابع حالته أو افتح لوحته.',`<button class="btn primary" data-action="add-shop">${icon('plus')} إضافة نشاط</button>`)+shopsCards();}
function shopsCards(){return `<div class="admin-shops">${db.shops.map(s=>`<article class="shop-card"><div class="shop-card-head"><span class="avatar" style="background:${esc(s.card.color)};color:${esc(s.card.accent)}">${icon(s.card.icon)}</span><div><h2>${esc(s.name)}</h2><p>${esc(s.card.category)} · ${esc(s.branch)}</p></div></div><span class="pill ${s.status==='active'?'':'gray'}">${s.status==='active'?'فعّال':'موقوف'}</span><div class="shop-metrics"><div><b>${fmt(s.members.length)}</b><span>بطاقات</span></div><div><b>${fmt(s.employees.length)}</b><span>موظفون</span></div><div><b>${fmt(s.logs.filter(l=>l.type==='stamp').length)}</b><span>أختام</span></div></div><div class="actions"><button class="btn secondary small" data-action="open-shop" data-id="${s.id}">فتح اللوحة</button><button class="btn quiet small" data-action="toggle-shop" data-id="${s.id}">${s.status==='active'?'إيقاف':'تفعيل'}</button></div></article>`).join('')}</div>`;}
function modal(title,body,actions=''){const d=document.querySelector('#modal');d.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" data-action="close-modal" aria-label="إغلاق">×</button></div>${body}${actions?`<div class="modal-actions">${actions}</div>`:''}`;d.showModal();}
function normalizePhone(raw){const n=String(raw).replace(/[٠-٩]/g,c=>'٠١٢٣٤٥٦٧٨٩'.indexOf(c)).replace(/[\s()-]/g,'');if(/^05\d{8}$/.test(n))return n;if(/^(\+?966|00966)5\d{8}$/.test(n))return '0'+n.slice(-9);return '';}
function processScan(raw){const s=shop();if(s.status!=='active'){toast('النشاط موقوف.');return;}const e=s.employees.find(e=>e.id===staffEmployee&&e.status==='active');if(!e){toast('اختر موظفًا نشطًا.');return;}let id=raw.trim();if(id.startsWith('RIJAA:')){const p=id.split(':');if(p.length!==3||p[1]!==s.id){toast('البطاقة تخص نشاطًا آخر.');return;}id=p[2];}const m=s.members.find(m=>m.id===id);if(!m){toast('لم نجد البطاقة في هذا النشاط.');return;}if(staffMode==='redeem'&&m.rewards<1){toast('لا توجد مكافأة جاهزة لهذا العميل.');return;}const before={stamps:m.stamps,rewards:m.rewards,visits:m.visits};let earned=false;if(staffMode==='stamp'){m.stamps++;m.visits++;if(m.stamps>=s.card.target){m.stamps-=s.card.target;m.rewards++;earned=true;}}else m.rewards--;const tx={id:crypto.randomUUID(),member:m.id,name:m.name||m.phone,type:staffMode,employee:e.name,time:Date.now()};s.logs.unshift(tx);if(earned)s.logs.unshift({...tx,id:crypto.randomUUID(),type:'reward'});lastTx={...tx,shop:s.id,before,earned,stamps:m.stamps,undone:false};selectedStaffMember=m.id;save();if(stream){const result=document.querySelector('#scan-status');result.textContent=`${staffMode==='stamp'?'تمت إضافة الختم':'تم صرف المكافأة'} — ${m.name||m.phone}`;toast(result.textContent);scannerLock=true;}else render();}
async function startCamera(){if(!navigator.mediaDevices?.getUserMedia){toast('الكاميرا غير متاحة. استخدم الرمز أو قارئ الباركود.');return;}try{stopCamera();stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment',width:{ideal:1280}},audio:false});const v=document.querySelector('#scan-video');if(!v){stopCamera();return;}v.srcObject=stream;await v.play();let detector=null;try{if('BarcodeDetector' in window)detector=new BarcodeDetector({formats:['qr_code','code_128']});}catch{}const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d',{willReadFrequently:true});const zreader=typeof ZXing!=='undefined'?new ZXing.MultiFormatReader():null;let missing=0,last=0;document.querySelector('#scan-status').textContent='ضع رمز بطاقة العميل داخل الإطار.';const loop=async time=>{if(!stream)return;if(time-last<150){scanFrame=requestAnimationFrame(loop);return;}last=time;try{let value='';if(detector){const codes=await detector.detect(v);value=codes[0]?.rawValue||'';}if(!value&&v.readyState>=2){canvas.width=Math.min(960,v.videoWidth);canvas.height=Math.round(v.videoHeight*canvas.width/v.videoWidth);ctx.drawImage(v,0,0,canvas.width,canvas.height);const data=ctx.getImageData(0,0,canvas.width,canvas.height);if(typeof jsQR==='function')value=jsQR(data.data,data.width,data.height,{inversionAttempts:'dontInvert'})?.data||'';if(!value&&zreader){const lum=new Uint8ClampedArray(data.width*data.height);for(let i=0;i<lum.length;i++)lum[i]=(data.data[4*i]+2*data.data[4*i+1]+data.data[4*i+2])>>2;try{value=zreader.decode(new ZXing.BinaryBitmap(new ZXing.HybridBinarizer(new ZXing.RGBLuminanceSource(lum,data.width,data.height)))).getText();}catch{}}}if(value){missing=0;if(!scannerLock){scannerLock=true;await processScan(value);}}else if(++missing>8)scannerLock=false;}catch{}if(stream)scanFrame=requestAnimationFrame(loop);};scanFrame=requestAnimationFrame(loop);}catch{stopCamera();toast('تعذر فتح الكاميرا. اسمح باستخدامها أو جرّب المحاكاة.');}}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;event.preventDefault();const a=b.dataset.action;if(a==='role'){role=b.dataset.role;view=role==='staff'?'scan':'overview';lastTx=null;render();}else if(a==='nav'){view=b.dataset.view;if(view==='design')draft=structuredClone(shop().card);render();}else if(a==='help'){modal('عن تجربة رِجعة','<p>تجربة متكاملة لمراجعة التصميم وسهولة الاستخدام. البيانات محفوظة في هذا المتصفح فقط.</p><div class="help-list"><div class="help-item"><strong>يمكنك تجربة</strong><p>تصميم البطاقة، التسجيل برقم تجريبي، الأختام والمكافآت، الموظفين وإدارة الأنشطة.</p></div><div class="help-item"><strong>قبل التشغيل الفعلي</strong><p>نربط قاعدة بيانات مشتركة، تسجيل الدخول والصلاحيات، رسائل التحقق، وإصدار وتحديث بطاقات Apple وGoogle.</p></div></div>');}else if(a==='reset'){modal('إعادة ضبط التجربة','<p>ستُحذف التغييرات المحلية وتعود بيانات العرض الأساسية.</p>','<button class="btn secondary" data-action="close-modal">إلغاء</button><button class="btn danger" data-action="confirm-reset">إعادة الضبط</button>');}else if(a==='confirm-reset'){db=seed();draft=null;lastTx=null;selectedStaffMember='';clientStage='phone';save();document.querySelector('#modal').close();render();toast('أعدنا بيانات التجربة.');}else if(a==='close-modal')document.querySelector('#modal').close();else if(a==='color'){draft.color=b.dataset.value;render();}else if(a==='clear-background'){draft.background='';render();}else if(a==='clear-stamp'){draft.stampImage='';render();}else if(a==='card-icon'){draft.icon=b.dataset.icon;draft.stampImage='';render();}else if(a==='pattern'){draft.pattern=b.dataset.value==='dots';render();}else if(a==='remove-logo'){draft.logo='';render();}else if(a==='save-card'){if(!draft.reward.trim()){toast('أدخل اسم المكافأة.');return;}if(draft.target!==shop().card.target&&shop().members.some(m=>m.stamps>0)){modal('تغيير عدد الزيارات','<p>لدى عملاء أختام حالية. لتجنب تغيير استحقاقهم، أبقِ عدد الزيارات الحالي في هذه التجربة. يمكن تعديل الألوان والاسم والمكافأة.</p>');return;}shop().card=structuredClone(draft);if(draft.name.trim())shop().name=draft.name.trim();save();view='mycards';render();toast('تم حفظ البطاقة.');}else if(a==='template'){const t=templates.find(t=>t.id===b.dataset.id);draft={...structuredClone(t),name:shop().name,logo:shop().card.logo,target:shop().members.some(m=>m.stamps>0)?shop().card.target:t.target};role='owner';view='design';render();toast('القالب جاهز للتعديل. احفظه عند الانتهاء.');}else if(a==='add-employee'){modal('إضافة موظف',`<form id="employee-form"><label class="field"><span>اسم الموظف</span><input class="input" name="name" maxlength="35" required></label><label class="field"><span>رقم الجوال</span><input class="input" name="phone" type="tel" dir="ltr" placeholder="05xxxxxxxx" required></label><p class="error" id="employee-error"></p><button type="submit" class="btn primary full">إضافة الموظف</button></form>`);}else if(a==='toggle-employee'){const e=shop().employees.find(e=>e.id===b.dataset.id);e.status=e.status==='active'?'paused':'active';save();render();toast(e.status==='active'?'تم تفعيل الموظف.':'تم إيقاف وصول الموظف.');}else if(a==='member-card'){const m=shop().members.find(m=>m.id===b.dataset.id);modal('بطاقة العميل',cardHTML(shop().card,m,true),`<button class="btn primary" data-action="choose-client" data-id="${m.id}">تجربة هذه البطاقة</button>`);}else if(a==='choose-client'){db.member=b.dataset.id;save();role='client';clientStage='card';document.querySelector('#modal').close();render();}else if(a==='copy-link'){try{await navigator.clipboard.writeText(joinURL());toast('تم نسخ رابط التسجيل.');}catch{modal('رابط التسجيل',`<input class="input" dir="ltr" readonly value="${esc(joinURL())}">`);}}else if(a==='download-qr'){const blob=new Blob([qr(joinURL())],{type:'image/svg+xml'});const u=URL.createObjectURL(blob);const link=document.createElement('a');link.href=u;link.download='rijaa-registration.svg';link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}else if(a==='staff-mode'){staffMode=b.dataset.mode;lastTx=null;scannerLock=false;render();}else if(a==='simulate-scan'){processScan(document.querySelector('#staff-member').value);}else if(a==='manual-scan'){processScan(document.querySelector('#manual-code').value);}else if(a==='camera'){scannerLock=false;await startCamera();}else if(a==='undo'){if(!lastTx||lastTx.undone||lastTx.shop!==shop().id)return;const m=shop().members.find(m=>m.id===lastTx.member);const idx=shop().logs.findIndex(l=>l.id===lastTx.id);if(idx<0||shop().logs.slice(0,idx).some(l=>l.member===m.id&&l.type!=='reward')){toast('حدثت عملية لاحقة لهذه البطاقة. لا يمكن التراجع تلقائيًا.');return;}Object.assign(m,lastTx.before);shop().logs.unshift({id:crypto.randomUUID(),member:m.id,name:m.name||m.phone,type:'undo',employee:shop().employees.find(e=>e.id===staffEmployee)?.name||lastTx.employee,time:Date.now()});lastTx.undone=true;save();render();toast('تم التراجع وإعادة الرصيد السابق.');}else if(a==='terms')modal('شروط برنامج الولاء',`<p>${esc(shop().card.terms)}</p><div class="notice">في النسخة الفعلية، ستُضاف سياسة خصوصية توضح استخدام رقم الجوال وحفظه.</div>`);else if(a==='back-phone'){clientStage='phone';render();}else if(a==='existing-client'){clientStage='card';render();}else if(a==='wallet'){modal(`معاينة ${esc(b.dataset.kind)}`,`${cardHTML(shop().card,currentMember(),true)}<div class="notice">هذه معاينة داخل الموقع، ولم تتم إضافة بطاقة إلى محفظة الجوال. الإصدار الفعلي يحتاج ربط حسابات وشهادات آبل وجوجل.</div>`);}else if(a==='client-to-staff'){selectedStaffMember=db.member;role='staff';view='scan';lastTx=null;render();}else if(a==='open-shop'){db.shop=b.dataset.id;db.member=shop().members[0]?.id||'';draft=null;lastTx=null;selectedStaffMember='';role='owner';view='overview';clientStage='phone';save();render();}else if(a==='toggle-shop'){const s=db.shops.find(s=>s.id===b.dataset.id);s.status=s.status==='active'?'paused':'active';save();render();toast(s.status==='active'?'تم تفعيل النشاط.':'تم إيقاف النشاط.');}else if(a==='add-shop'){modal('إضافة نشاط',`<form id="shop-form"><label class="field"><span>اسم النشاط</span><input class="input" name="name" maxlength="36" required></label><label class="field"><span>القالب</span><select name="template">${templates.map(t=>`<option value="${t.id}">${esc(t.category)}</option>`).join('')}</select></label><label class="field"><span>اسم الفرع</span><input class="input" name="branch" value="الفرع الرئيسي" maxlength="40" required></label><button type="submit" class="btn primary full">إنشاء النشاط</button></form>`);}});
document.addEventListener('input',e=>{if(e.target.getAttribute("id")==='customer-search'){const q=e.target.value.trim();document.querySelector('#customer-rows').innerHTML=customerRows(shop().members.filter(m=>m.name.includes(q)||m.phone.includes(q)||m.id.includes(q)));}});
document.addEventListener('change',e=>{if(e.target.getAttribute("id")==='staff-employee'){staffEmployee=e.target.value;lastTx=null;}if(e.target.getAttribute("id")==='staff-member')selectedStaffMember=e.target.value;});
document.addEventListener('keydown',e=>{if(e.target.getAttribute("id")==='manual-code'&&e.key==='Enter'){e.preventDefault();processScan(e.target.value);}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(f.getAttribute("id")==='join-form'){const phone=normalizePhone(d.get('phone'));if(!phone){document.querySelector('#join-error').textContent='أدخل رقم جوال سعودي صحيح يبدأ بـ 05.';return;}if(shop().status!=='active'){document.querySelector('#join-error').textContent='التسجيل في هذا النشاط متوقف حاليًا.';return;}clientPhone=phone;clientName=String(d.get('name')).trim();clientStage='otp';render();}else if(f.getAttribute("id")==='otp-form'){if(d.get('otp')!=='123456'){document.querySelector('#otp-error').textContent='رمز التجربة غير صحيح. استخدم 123456.';return;}let m=shop().members.find(m=>m.phone===clientPhone);if(!m){m={id:'RJ-'+crypto.randomUUID().slice(0,8).toUpperCase(),name:clientName||'عميل رِجعة',phone:clientPhone,stamps:0,rewards:0,visits:0,joined:Date.now()};shop().members.push(m);}db.member=m.id;save();clientStage='card';render();toast('بطاقتك جاهزة.');}else if(f.getAttribute("id")==='employee-form'){const phone=normalizePhone(d.get('phone')),name=String(d.get('name')).trim();if(!name||!phone){document.querySelector('#employee-error').textContent='أدخل الاسم ورقم جوال صحيحًا.';return;}if(shop().employees.some(e=>e.phone===phone)){document.querySelector('#employee-error').textContent='هذا الموظف مضاف بالفعل.';return;}shop().employees.push({id:crypto.randomUUID(),name,phone,status:'active'});save();document.querySelector('#modal').close();render();toast('تمت إضافة الموظف. لم تُرسل دعوة فعلية في التجربة.');}else if(f.getAttribute("id")==='shop-form'){const name=String(d.get('name')).trim();if(!name)return;const t=templates.find(t=>t.id===d.get('template'));db.shops.push({id:crypto.randomUUID(),name,status:'active',branch:String(d.get('branch')).trim(),card:{...structuredClone(t),name,logo:''},employees:[],members:[],logs:[]});save();document.querySelector('#modal').close();render();toast('تم إنشاء النشاط.');}});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{db=JSON.parse(e.newValue);render();}catch{}}});
const params=new URLSearchParams(location.search);if(params.has('join')){const s=db.shops.find(s=>s.id===params.get('join'));if(s){db.shop=s.id;db.member=s.members[0]?.id||'';role='client';clientStage='phone';}else toast('رابط النشاط غير متاح في بيانات هذا المتصفح.');}
save();render();

